create or replace function public.submit_amenity_observation(p_location_id uuid,p_amenity_id uuid,p_status text,p_confidence numeric default null,p_verification_method text default 'user',p_check_in_id uuid default null,p_photo_id uuid default null,p_notes text default null,p_metadata jsonb default '{}') returns public.location_amenity_observations language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare uid uuid:=auth.uid(); r public.location_amenity_observations; v_check public.check_ins%rowtype; v_eligible boolean:=false; v_key text; begin if uid is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.locations where id=p_location_id and is_active=true) then raise exception 'Canonical location not found or inactive'; end if; if not exists(select 1 from public.amenities where id=p_amenity_id) then raise exception 'Amenity not found'; end if; if lower(coalesce(p_status,'')) not in ('present','absent','unknown') then raise exception 'Amenity status must be present, absent, or unknown'; end if; if p_check_in_id is not null then select * into v_check from public.check_ins where id=p_check_in_id; if not found or v_check.user_id<>uid or v_check.location_id<>p_location_id then raise exception 'Check-in does not belong to this user and canonical location'; end if; if v_check.checked_in_at>now()+interval '5 minutes' then raise exception 'Check-in timestamp is not valid'; end if; v_eligible:=public.is_qualifying_return_visit(uid,p_location_id,v_check.checked_in_at); end if; insert into public.location_amenity_observations(location_id,user_id,amenity_id,status,confidence,verification_method,check_in_id,photo_id,notes,observed_at,metadata) values(p_location_id,uid,p_amenity_id,lower(p_status),p_confidence,p_verification_method,p_check_in_id,p_photo_id,p_notes,now(),coalesce(p_metadata,'{}')) returning * into r; if v_eligible and p_check_in_id is not null then v_key:=md5(concat_ws('|',uid::text,'amenity_observation',p_check_in_id::text,p_location_id::text,p_amenity_id::text)); perform public.record_progression_metric_event('verification','amenity_observation',r.id,1,15,jsonb_build_object('idempotency_key',v_key,'location_id',p_location_id,'amenity_id',p_amenity_id,'check_in_id',p_check_in_id,'evidence_id',r.id,'evidence_type','amenity_observation','server_authoritative',true)); end if; return r; end $$;
